class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def getMaxSum(root):
    def dfs(node):
        if not node:
            return (0, 0)
        left_choose, left_not_choose = dfs(node.left)
        right_choose, right_not_choose = dfs(node.right)
        choose = node.val + left_not_choose + right_not_choose
        not_choose = max(left_choose, left_not_choose) + max(right_choose, right_not_choose)
        return (choose, not_choose)

    return max(dfs(root))

import sys
from collections import deque

def build_tree(index, nodes):
    if index < len(nodes) and nodes[index] != 'null':
        node = TreeNode(int(nodes[index]))
        node.left = build_tree(2 * index + 1, nodes)
        node.right = build_tree(2 * index + 2, nodes)
        return node
    return None

input = sys.stdin.read().strip()
nodes = input.split()
root = build_tree(0, nodes)
print(getMaxSum(root))
